CREATE FUNCTION public.business_minutes_between(p_calendar uuid,p_from timestamptz,p_to timestamptz) RETURNS int LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.business_calendars; d date; a timestamp; b timestamp; total numeric:=0; BEGIN SELECT * INTO STRICT c FROM public.business_calendars WHERE id=p_calendar; IF p_to<=p_from THEN RETURN 0; END IF; a:=p_from AT TIME ZONE c.timezone; b:=p_to AT TIME ZONE c.timezone; FOR d IN SELECT generate_series(a::date,b::date,interval '1 day')::date LOOP IF extract(isodow FROM d)::smallint=ANY(c.work_days) AND NOT EXISTS(SELECT 1 FROM public.holidays WHERE calendar_id=c.id AND day=d) THEN total:=total+greatest(0,extract(epoch FROM (least(b,d+c.work_end)-greatest(a,d+c.work_start)))/60); END IF; END LOOP; RETURN floor(total)::int; END $$;
CREATE FUNCTION public.add_business_minutes(p_calendar uuid,p_start timestamptz,p_minutes int) RETURNS timestamptz LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.business_calendars; t timestamp; left_minutes numeric; room numeric; days int:=0; BEGIN IF p_minutes<0 THEN RAISE EXCEPTION 'Minutos úteis devem ser positivos'; END IF; SELECT * INTO STRICT c FROM public.business_calendars WHERE id=p_calendar; t:=p_start AT TIME ZONE c.timezone; left_minutes:=p_minutes; LOOP days:=days+1; IF days>36600 THEN RAISE EXCEPTION 'Calendário sem expediente disponível'; END IF; IF extract(isodow FROM t)::smallint=ANY(c.work_days) AND NOT EXISTS(SELECT 1 FROM public.holidays WHERE calendar_id=c.id AND day=t::date) THEN t:=greatest(t,t::date+c.work_start); room:=greatest(0,extract(epoch FROM ((t::date+c.work_end)-t))/60); IF left_minutes<=room THEN RETURN (t+left_minutes*interval '1 minute') AT TIME ZONE c.timezone; END IF; left_minutes:=left_minutes-room; END IF; t:=(t::date+1)+c.work_start; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.business_minutes_between(uuid,timestamptz,timestamptz),public.add_business_minutes(uuid,timestamptz,int) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.business_minutes_between(uuid,timestamptz,timestamptz),public.add_business_minutes(uuid,timestamptz,int) TO authenticated,service_role;
CREATE FUNCTION public.preview_sla(p_account_id uuid,p_impact public.occ_level,p_urgency public.occ_level) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.accounts; t public.sla_targets; c public.business_calendars; s public.occ_severity; BEGIN IF NOT public.has_account_access(p_account_id) THEN RAISE EXCEPTION 'Sem acesso à conta'; END IF; SELECT * INTO STRICT a FROM public.accounts WHERE id=p_account_id; s:=public.calculate_severity(p_impact,p_urgency); SELECT * INTO STRICT t FROM public.sla_targets WHERE policy_id=a.sla_policy_id AND severity=s; SELECT * INTO STRICT c FROM public.business_calendars WHERE id=a.calendar_id; RETURN jsonb_build_object('severity',s,'first_response_minutes',t.first_response_minutes,'resolution_minutes',t.resolution_minutes,'update_interval_minutes',t.update_interval_minutes,'calendar',c.name,'timezone',c.timezone,'first_response_due_at',public.add_business_minutes(c.id,now(),t.first_response_minutes),'resolution_due_at',public.add_business_minutes(c.id,now(),t.resolution_minutes)); END $$;
REVOKE ALL ON FUNCTION public.preview_sla(uuid,public.occ_level,public.occ_level) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.preview_sla(uuid,public.occ_level,public.occ_level) TO authenticated;
CREATE FUNCTION public.initialize_occurrence_sla() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.accounts; t public.sla_targets; BEGIN SELECT * INTO STRICT a FROM public.accounts WHERE id=NEW.account_id AND active; SELECT * INTO STRICT t FROM public.sla_targets WHERE policy_id=a.sla_policy_id AND severity=public.calculate_severity(NEW.impact,NEW.urgency); NEW.created_at:=now(); NEW.status:='registered'; NEW.severity:=t.severity; NEW.resolution_started_at:=NEW.created_at; NEW.first_response_due_at:=public.add_business_minutes(a.calendar_id,NEW.created_at,t.first_response_minutes); NEW.resolution_due_at:=public.add_business_minutes(a.calendar_id,NEW.created_at,t.resolution_minutes); NEW.first_response_at:=NULL; NEW.first_response_breached:=false; NEW.resolution_breached:=false; NEW.paused_business_minutes:=0; NEW.reopen_count:=0; NEW.solution_proposed_at:=NULL; NEW.closed_at:=NULL; RETURN NEW; END $$;
CREATE TRIGGER occurrence_sla_init BEFORE INSERT ON public.occurrences FOR EACH ROW EXECUTE FUNCTION public.initialize_occurrence_sla();
CREATE FUNCTION public.record_opening_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body) VALUES(NEW.id,'system','system',NEW.created_by,'Ocorrência registrada.'); RETURN NEW; END $$;
CREATE TRIGGER occurrence_open_event AFTER INSERT ON public.occurrences FOR EACH ROW EXECUTE FUNCTION public.record_opening_event();
CREATE FUNCTION public.available_transitions(p_occurrence_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.occurrences; role public.user_role; permitted boolean; result jsonb:='[]'; BEGIN IF NOT public.has_occurrence_access(p_occurrence_id) THEN RAISE EXCEPTION 'Sem acesso à ocorrência'; END IF; SELECT * INTO STRICT o FROM public.occurrences WHERE id=p_occurrence_id; role:=public.current_app_role(); permitted:=role IN ('kam','ops_manager') OR (role='analyst' AND o.assignee_id=auth.uid()); IF o.status='registered' AND role IN ('analyst','kam','ops_manager') THEN result:=result||jsonb_build_array(jsonb_build_object('action','assume','label','Assumir ocorrência','allowed',true,'conditions','[]'::jsonb)); END IF; IF o.status='in_analysis' AND permitted THEN result:=result||jsonb_build_array(jsonb_build_object('action','start_treatment','label','Iniciar tratativa','allowed',o.first_response_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.actions WHERE occurrence_id=o.id AND type='containment'),'conditions',jsonb_build_array(jsonb_build_object('label','Primeira resposta enviada','met',o.first_response_at IS NOT NULL),jsonb_build_object('label','Ação de contenção cadastrada','met',EXISTS(SELECT 1 FROM public.actions WHERE occurrence_id=o.id AND type='containment'))))); END IF; IF o.status IN ('in_analysis','in_treatment','reopened') AND permitted THEN result:=result||jsonb_build_array(jsonb_build_object('action','ask_customer','label','Pedir informação ao cliente','allowed',true,'conditions','[]'::jsonb)); END IF; IF o.status='awaiting_customer' AND permitted THEN result:=result||jsonb_build_array(jsonb_build_object('action','customer_replied','label','Registrar resposta e retomar SLA','allowed',true,'conditions','[]'::jsonb)); END IF; IF o.status IN ('in_treatment','reopened') AND permitted THEN result:=result||jsonb_build_array(jsonb_build_object('action','propose_solution','label','Registrar solução','allowed',NOT EXISTS(SELECT 1 FROM public.actions WHERE occurrence_id=o.id AND gates_solution AND status<>'done') AND (o.severity NOT IN ('S1','S2') OR o.problem_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.causes WHERE occurrence_id=o.id AND kind='root' AND status='confirmed')),'conditions',jsonb_build_array(jsonb_build_object('label','Contenção e correção concluídas','met',NOT EXISTS(SELECT 1 FROM public.actions WHERE occurrence_id=o.id AND gates_solution AND status<>'done')),jsonb_build_object('label','Causa raiz confirmada ou problema vinculado para S1/S2','met',o.severity NOT IN ('S1','S2') OR o.problem_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.causes WHERE occurrence_id=o.id AND kind='root' AND status='confirmed'))))); END IF; IF o.status='in_analysis' AND role IN ('kam','ops_manager') THEN result:=result||jsonb_build_array(jsonb_build_object('action','mark_unfounded','label','Marcar como improcedente','allowed',EXISTS(SELECT 1 FROM public.attachments WHERE occurrence_id=o.id),'conditions',jsonb_build_array(jsonb_build_object('label','Evidência anexada','met',EXISTS(SELECT 1 FROM public.attachments WHERE occurrence_id=o.id))))); END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.available_transitions(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.available_transitions(uuid) TO authenticated;
CREATE FUNCTION public.transition_occurrence(p_occurrence_id uuid,p_action text,p_payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.occurrences; a public.accounts; t public.sla_targets; target public.occ_status; body text; allowed boolean; token text; BEGIN IF NOT public.has_occurrence_access(p_occurrence_id) THEN RAISE EXCEPTION 'Sem acesso à ocorrência'; END IF; SELECT * INTO STRICT o FROM public.occurrences WHERE id=p_occurrence_id FOR UPDATE; SELECT coalesce((v->>'allowed')::boolean,false) INTO allowed FROM jsonb_array_elements(public.available_transitions(o.id)) v WHERE v->>'action'=p_action; IF NOT coalesce(allowed,false) THEN RAISE EXCEPTION 'Transição não permitida ou condições pendentes'; END IF; SELECT * INTO STRICT a FROM public.accounts WHERE id=o.account_id; SELECT * INTO STRICT t FROM public.sla_targets WHERE policy_id=a.sla_policy_id AND severity=o.severity; body:=trim(coalesce(p_payload->>'body','')); CASE p_action WHEN 'assume' THEN target:='in_analysis'; UPDATE public.occurrences SET assignee_id=auth.uid() WHERE id=o.id; WHEN 'start_treatment' THEN target:='in_treatment'; WHEN 'ask_customer' THEN IF body='' THEN RAISE EXCEPTION 'Informe a pergunta ao cliente'; END IF; target:='awaiting_customer'; UPDATE public.occurrences SET paused_since=now(),first_response_at=coalesce(first_response_at,now()),first_response_breached=first_response_breached OR (first_response_at IS NULL AND now()>first_response_due_at) WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body,metadata) VALUES(o.id,'customer_question','customer',auth.uid(),body,jsonb_build_object('previous_status',o.status)); WHEN 'customer_replied' THEN IF body='' THEN RAISE EXCEPTION 'Informe a resposta recebida'; END IF; SELECT (metadata->>'previous_status')::public.occ_status INTO target FROM public.occurrence_events WHERE occurrence_id=o.id AND kind='customer_question' ORDER BY created_at DESC LIMIT 1; target:=coalesce(target,'in_treatment'); UPDATE public.occurrences SET paused_business_minutes=paused_business_minutes+public.business_minutes_between(a.calendar_id,o.paused_since,now()),paused_since=NULL,resolution_due_at=public.add_business_minutes(a.calendar_id,o.resolution_started_at,t.resolution_minutes+o.paused_business_minutes+public.business_minutes_between(a.calendar_id,o.paused_since,now())) WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body) VALUES(o.id,'customer_reply','internal',auth.uid(),body); WHEN 'propose_solution' THEN IF length(body)<20 THEN RAISE EXCEPTION 'Descreva a solução com pelo menos 20 caracteres'; END IF; target:='solution_proposed'; UPDATE public.occurrences SET solution_text=body,solution_proposed_at=now(),resolution_breached=resolution_breached OR now()>resolution_due_at WHERE id=o.id; WHEN 'mark_unfounded' THEN IF length(body)<30 THEN RAISE EXCEPTION 'Justifique com pelo menos 30 caracteres'; END IF; target:='closed_unfounded'; UPDATE public.occurrences SET unfounded_justification=body,closed_at=now() WHERE id=o.id; ELSE RAISE EXCEPTION 'Ação inválida'; END CASE; UPDATE public.occurrences SET status=target,updated_at=now() WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body,from_status,to_status) VALUES(o.id,'status_change','system',auth.uid(),nullif(body,''),o.status,target); RETURN jsonb_build_object('status',target); END $$;
REVOKE ALL ON FUNCTION public.transition_occurrence(uuid,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.transition_occurrence(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.communicate_occurrence(p_occurrence_id uuid,p_kind public.event_kind,p_body text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.occurrences; a public.accounts; t public.sla_targets; BEGIN SELECT * INTO STRICT o FROM public.occurrences WHERE id=p_occurrence_id FOR UPDATE; IF NOT public.can_manage_work(o.id,NULL) OR p_kind NOT IN ('customer_update','internal_note') OR length(trim(p_body))=0 THEN RAISE EXCEPTION 'Comunicação não permitida'; END IF; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body) VALUES(o.id,p_kind,CASE WHEN p_kind='internal_note' THEN 'internal'::public.event_visibility ELSE 'customer'::public.event_visibility END,auth.uid(),p_body); IF p_kind='customer_update' THEN SELECT * INTO a FROM public.accounts WHERE id=o.account_id; SELECT * INTO t FROM public.sla_targets WHERE policy_id=a.sla_policy_id AND severity=o.severity; UPDATE public.occurrences SET first_response_at=coalesce(first_response_at,now()),first_response_breached=first_response_breached OR (first_response_at IS NULL AND now()>first_response_due_at),next_update_due_at=public.add_business_minutes(a.calendar_id,now(),t.update_interval_minutes) WHERE id=o.id; END IF; END $$;
REVOKE ALL ON FUNCTION public.communicate_occurrence(uuid,public.event_kind,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.communicate_occurrence(uuid,public.event_kind,text) TO authenticated;
CREATE VIEW public.v_occurrence_sla WITH (security_invoker=true) AS SELECT o.id,o.first_response_due_at,o.resolution_due_at,CASE WHEN o.status='awaiting_customer' THEN 'paused' WHEN o.status IN ('solution_proposed','closed_resolved','closed_no_evaluation','closed_unfounded') THEN 'stopped' WHEN now()>o.resolution_due_at THEN 'breached' WHEN public.business_minutes_between(a.calendar_id,o.resolution_started_at,now())-o.paused_business_minutes>=t.resolution_minutes*0.8 THEN 'risk' ELSE 'ok' END AS sla_state,least(100,greatest(0,(public.business_minutes_between(a.calendar_id,o.resolution_started_at,coalesce(o.solution_proposed_at,o.paused_since,now()))-o.paused_business_minutes)*100.0/t.resolution_minutes)) AS consumed_percent FROM public.occurrences o JOIN public.accounts a ON a.id=o.account_id JOIN public.sla_targets t ON t.policy_id=a.sla_policy_id AND t.severity=o.severity;
GRANT SELECT ON public.v_occurrence_sla TO authenticated,service_role;